root.innerHTML = `
  <svg style="position:absolute;width:940px;height:1060px;fill:none;stroke:#ffffff;stroke-width:10;stroke-linecap:round;opacity:0.3">
    <path id="l0" d="M470 300 L470 340" />
    <path id="l1" d="M470 580 L470 620" />
  </svg>
  <div id="c0" style="${STY('var(--acc)')}top:60px;">
    <div style="font-size:38px;opacity:0.7;margin-bottom:8px">MODELS BYPASSING</div>
    <div style="font-size:62px">PROTOCOLS</div>
  </div>
  <div id="c1" style="${STY('var(--acc2)')}top:340px;">
    <div style="font-size:38px;opacity:0.7;margin-bottom:8px">TASK EXECUTION</div>
    <div style="font-size:62px">AUTONOMOUS AGENTS</div>
  </div>
  <div id="c2" style="${STY('#ffffff')}top:620px;height:380px;background:#ffffff;">
    <div style="font-size:38px;opacity:0.7;margin-bottom:20px">INCIDENTS LOGGED</div>
    <div id="cnt" style="font-size:110px;margin-bottom:20px;color:var(--acc)">1</div>
    <div style="font-size:40px;background:#0b1020;color:#ffffff;padding:12px 40px;border-radius:100px">NOT A ONE-TIME FLUKE</div>
  </div>
`;

const items = [root.querySelector('#c0'), root.querySelector('#c1'), root.querySelector('#c2')];
const cnt = root.querySelector('#cnt');
const lines = [root.querySelector('#l0'), root.querySelector('#l1')].map(l => {
  const len = l.getTotalLength();
  l.style.strokeDasharray = len;
  l.style.strokeDashoffset = len;
  return { l, len };
});

function frame(t, p, d) {
  const tf = p >= 0.55 ? d * 0.55 : t;
  const delays = [0.1, 0.9, 1.7];

  items.forEach((el, i) => {
    const s = spr(tf, delays[i], 0.8, 8);
    el.style.opacity = clamp(s * 2);
    const scale = lerp(0.85, 1, E_OUT(clamp(s)));
    const slide = lerp(40, 0, E_OUT(clamp(s)));
    el.style.transform = `translateY(${slide}px) scale(${scale})`;
  });

  const lDelays = [0.7, 1.5];
  lines.forEach((line, i) => {
    const s = spr(tf, lDelays[i], 0.9, 6);
    line.l.style.strokeDashoffset = line.len * (1 - clamp(s));
  });

  const cS = spr(tf, 2.1, 0.9, 5);
  const val = Math.floor(lerp(1, 10, clamp(cS)));
  cnt.textContent = val >= 9 ? "MULTIPLE" : val;
  cnt.style.color = val >= 9 ? 'var(--acc2)' : 'var(--acc)';
  cnt.style.transform = `scale(${lerp(1, 1.1, E_OUT(clamp(cS - 0.8)))})`;
}
